+describe("007_add_login_permissions backfill", () => {
+	const ORG = "org-login-backfill";
+
+	type Seed = {
+		slug: string;
+		isSystem: boolean;
+		deleted: boolean;
+		permissions: Array<{
+			client: "bo" | "pos";
+			key: string;
+			modifier: "grant" | "deny";
+		}>;
+	};
+
+	const seeds: Seed[] = [
+		{
+			slug: "bo-only",
+			isSystem: false,
+			deleted: false,
+			permissions: [{ client: "bo", key: "orders.read", modifier: "grant" }],
+		},
+		{
+			slug: "pos-only",
+			isSystem: false,
+			deleted: false,
+			permissions: [{ client: "pos", key: "register.open", modifier: "grant" }],
+		},
+		{
+			slug: "both-clients",
+			isSystem: false,
+			deleted: false,
+			permissions: [
+				{ client: "bo", key: "orders.read", modifier: "grant" },
+				{ client: "pos", key: "register.open", modifier: "grant" },
+			],
+		},
+		{
+			slug: "no-permissions",
+			isSystem: false,
+			deleted: false,
+			permissions: [],
+		},
+		{
+			slug: "deny-only",
+			isSystem: false,
+			deleted: false,
+			permissions: [{ client: "bo", key: "orders.read", modifier: "deny" }],
+		},
+		{
+			slug: "sitoo-system-role",
+			isSystem: true,
+			deleted: false,
+			permissions: [{ client: "bo", key: "orders.read", modifier: "grant" }],
+		},
+		{
+			slug: "soft-deleted",
+			isSystem: false,
+			deleted: true,
+			permissions: [{ client: "bo", key: "orders.read", modifier: "grant" }],
+		},
+	];
+
+	async function connect() {
+		const client = new pg.Client({
+			host: DB_HOST,
+			port: DB_PORT,
+			user: DB_USER,
+			password: DB_PASSWORD,
+			database: TEST_DB,
+		});
+		await client.connect();
+		return client;
+	}
+
+	async function applyMigration(client: pg.Client) {
+		for (const stmt of splitStatements(m007)) {
+			await client.query(stmt);
+		}
+	}
+
+	/** Login keys per role slug, as `client:key`. */
+	async function loginKeysBySlug(client: pg.Client) {
+		const result = await client.query<{ slug: string; scoped: string }>(
+			`SELECT r.slug, rp.client || ':' || rp.permission_key AS scoped
+         FROM roles r
+         JOIN role_permissions rp ON rp.role_id = r.id
+        WHERE r.organization_id = $1
+          AND rp.permission_key IN ('backoffice.login', 'pos.login')
+        ORDER BY r.slug, scoped`,
+			[ORG],
+		);
+		const bySlug = new Map<string, string[]>();
+		for (const row of result.rows) {
+			bySlug.set(row.slug, [...(bySlug.get(row.slug) ?? []), row.scoped]);
+		}
+		return Object.fromEntries(bySlug);
+	}
+
+	beforeAll(async () => {
+		// Seed roles as they existed before this migration — no login permissions.
+		const client = await connect();
+		try {
+			for (const [index, seed] of seeds.entries()) {
+				const inserted = await client.query<{ id: string }>(
+					`INSERT INTO roles (
+             id, organization_id, environment, slug, name, description,
+             rank, status, is_system, created_by, created_at,
+             modified_by, updated_at, deleted_at
+           ) VALUES (
+             gen_random_uuid(), $1, 'production', $2, $2, NULL,
+             $3, 'active', $4, 'test', NOW(),
+             'test', NOW(), $5
+           ) RETURNING id`,
+					[
+						ORG,
+						seed.slug,
+						index + 1, // chk_rank: 1..99
+						seed.isSystem,
+						seed.deleted ? new Date() : null,
+					],
+				);
+				const roleId = inserted.rows[0]?.id;
+				for (const perm of seed.permissions) {
+					await client.query(
+						`INSERT INTO role_permissions (
+               id, role_id, client, permission_key, modifier, created_at
+             ) VALUES (gen_random_uuid(), $1, $2, $3, $4, NOW())`,
+						[roleId, perm.client, perm.key, perm.modifier],
+					);
+				}
+			}
+			await applyMigration(client);
+		} finally {
+			await client.end();
+		}
+	});
+
+	it("grants backoffice.login to custom roles holding any bo permission", async () => {
+		const client = await connect();
+		try {
+			const bySlug = await loginKeysBySlug(client);
+			expect(bySlug["bo-only"]).toEqual(["bo:backoffice.login"]);
+		} finally {
+			await client.end();
+		}
+	});
+
+	it("grants pos.login to custom roles holding any pos permission", async () => {
+		const client = await connect();
+		try {
+			const bySlug = await loginKeysBySlug(client);
+			expect(bySlug["pos-only"]).toEqual(["pos:pos.login"]);
+		} finally {
+			await client.end();
+		}
+	});
+
+	it("grants both to roles holding permissions in both clients", async () => {
+		const client = await connect();
+		try {
+			const bySlug = await loginKeysBySlug(client);
+			expect(bySlug["both-clients"]).toEqual([
+				"bo:backoffice.login",
+				"pos:pos.login",
+			]);
+		} finally {
+			await client.end();
+		}
+	});
+
+	it("leaves permissionless, deny-only, system and soft-deleted roles untouched", async () => {
+		const client = await connect();
+		try {
+			const bySlug = await loginKeysBySlug(client);
+			expect(bySlug["no-permissions"]).toBeUndefined();
+			expect(bySlug["deny-only"]).toBeUndefined();
+			expect(bySlug["sitoo-system-role"]).toBeUndefined();
+			expect(bySlug["soft-deleted"]).toBeUndefined();
+		} finally {
+			await client.end();
+		}
+	});
+
+	it("is idempotent — re-running inserts no duplicates", async () => {
+		const client = await connect();
+		try {
+			await applyMigration(client);
+			const bySlug = await loginKeysBySlug(client);
+			expect(bySlug["both-clients"]).toEqual([
+				"bo:backoffice.login",
+				"pos:pos.login",
+			]);
+		} finally {
+			await client.end();
+		}
+	});
+});

